import Combine
import CoreLocation
import Foundation

@MainActor
final class WeatherViewModel: ObservableObject {
    @Published var weather: WeatherResponse?
    @Published var locationName = "Ваше местоположение"
    @Published var isLoading = false
    @Published var errorMessage: String?
    @Published var searchResults: [PlaceResult] = []
    @Published var isSearching = false

    let locationManager = LocationManager()
    private let service = WeatherService()
    private var hasLoadedInitial = false
    private var cancellables: Set<AnyCancellable> = []

    var currentPresentation: WeatherPresentation {
        WeatherPresentation.from(code: weather?.current.weatherCode ?? 0, isDay: isCurrentlyDay)
    }

    var isCurrentlyDay: Bool {
        guard let weather,
              let sunriseText = weather.daily.sunrise.first,
              let sunsetText = weather.daily.sunset.first,
              let sunrise = WeatherDate.isoLocal.date(from: sunriseText),
              let sunset = WeatherDate.isoLocal.date(from: sunsetText),
              let current = WeatherDate.isoLocal.date(from: weather.current.time) else { return true }
        return current >= sunrise && current < sunset
    }

    var hourly: [HourForecast] {
        guard let weather, let current = WeatherDate.isoLocal.date(from: weather.current.time) else { return [] }
        return weather.hourly.time.indices.compactMap { i in
            guard i < weather.hourly.temperature2m.count, i < weather.hourly.weatherCode.count, i < weather.hourly.precipitationProbability.count,
                  let date = WeatherDate.isoLocal.date(from: weather.hourly.time[i]), date >= current.addingTimeInterval(-1800) else { return nil }
            return HourForecast(date: date, temperature: weather.hourly.temperature2m[i], code: weather.hourly.weatherCode[i], rainChance: weather.hourly.precipitationProbability[i])
        }.prefix(24).map { $0 }
    }

    var daily: [DayForecast] {
        guard let weather else { return [] }
        return weather.daily.time.indices.compactMap { i in
            guard i < weather.daily.weatherCode.count, i < weather.daily.temperature2mMax.count, i < weather.daily.temperature2mMin.count, i < weather.daily.precipitationProbabilityMax.count,
                  let date = WeatherDate.day.date(from: weather.daily.time[i]) else { return nil }
            return DayForecast(date: date, code: weather.daily.weatherCode[i], high: weather.daily.temperature2mMax[i], low: weather.daily.temperature2mMin[i], rainChance: weather.daily.precipitationProbabilityMax[i])
        }
    }

    init() {
        locationManager.$coordinate
            .compactMap { $0 }
            .removeDuplicates { lhs, rhs in
                abs(lhs.latitude - rhs.latitude) < 0.001 && abs(lhs.longitude - rhs.longitude) < 0.001
            }
            .sink { [weak self] coordinate in
                Task { @MainActor in
                    guard let self else { return }
                    await self.load(latitude: coordinate.latitude, longitude: coordinate.longitude, name: self.locationManager.placeName ?? "Ваше местоположение", save: true)
                }
            }
            .store(in: &cancellables)

        locationManager.$placeName
            .compactMap { $0 }
            .sink { [weak self] name in
                guard let self, self.locationName == "Ваше местоположение" else { return }
                self.locationName = name
            }
            .store(in: &cancellables)

        locationManager.$errorMessage
            .compactMap { $0 }
            .sink { [weak self] message in self?.errorMessage = message }
            .store(in: &cancellables)
    }

    func start() async {
        guard !hasLoadedInitial else { return }
        hasLoadedInitial = true
        let defaults = UserDefaults.standard
        if defaults.object(forKey: "savedLatitude") != nil {
            await load(latitude: defaults.double(forKey: "savedLatitude"), longitude: defaults.double(forKey: "savedLongitude"), name: defaults.string(forKey: "savedLocationName") ?? "Сохранённый город", save: false)
        } else {
            locationManager.requestLocation()
        }
    }

    func useCurrentLocation() {
        locationName = "Ваше местоположение"
        locationManager.requestLocation()
    }

    func refresh() async {
        let defaults = UserDefaults.standard
        guard defaults.object(forKey: "savedLatitude") != nil else {
            locationManager.requestLocation()
            return
        }
        await load(latitude: defaults.double(forKey: "savedLatitude"), longitude: defaults.double(forKey: "savedLongitude"), name: defaults.string(forKey: "savedLocationName") ?? locationName, save: false)
    }

    func select(place: PlaceResult) async {
        await load(latitude: place.latitude, longitude: place.longitude, name: place.name, save: true)
        searchResults = []
    }

    func search(query: String) async {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.count >= 2 else { searchResults = []; return }
        isSearching = true
        defer { isSearching = false }
        do { searchResults = try await service.searchPlaces(query: trimmed) }
        catch { searchResults = []; errorMessage = error.localizedDescription }
    }

    private func load(latitude: Double, longitude: Double, name: String, save: Bool) async {
        isLoading = true
        errorMessage = nil
        defer { isLoading = false }
        do {
            weather = try await service.fetchWeather(latitude: latitude, longitude: longitude)
            locationName = name
            if save {
                let defaults = UserDefaults.standard
                defaults.set(latitude, forKey: "savedLatitude")
                defaults.set(longitude, forKey: "savedLongitude")
                defaults.set(name, forKey: "savedLocationName")
            }
        } catch {
            errorMessage = error.localizedDescription
        }
    }
}
